#![allow(unreachable_code, dead_code, unused)]

use crate::Result;
use crate::models::order::Order;
use crate::models::user::User;
use kova::Options;
use kova::dsl::func::{Count, CumeDist, DenseRank, FrameBound, Lag, Lead, Ntile, PercentRank, Rank, RowNumber, Star, Sum};
use kova::dsl::{Identifier, Subselect};
use kova::types::{Cte, Relation};

// ==========================================
// Note: Simulating the virtual table generated by #[derive(Cte)]
// ==========================================
pub struct TopSpender;

// Standard Relation binding
impl Relation for TopSpender {
    const RELATION_NAME: &'static str = "top_spender";
}
// Tagging it as a CTE
impl Cte for TopSpender {}

#[allow(non_upper_case_globals)]
impl TopSpender {
    // Pure IdentifierMeta here-no heavy physical Column traits attached.
    pub const user_id: Identifier<i32> = Identifier::new("top_spender", "user_id");
    pub const total_amount: Identifier<f64> = Identifier::new("top_spender", "total_amount");
    pub const order_count: Identifier<i64> = Identifier::new("top_spender", "order_count");
}

// ==========================================
// Window Functions Boundary Tests
// ==========================================
async fn compile_check_window_functions() -> Result<()> {
    let client = Options::from("").build()?;

    let _ = client
        .select::<Order>()
        .columns((
            Order::id,
            Order::user_id,
            // Scenario A: Basic partition agg (COUNT(*) OVER (PARTITION BY user_id))
            Count(Star).over().partition_by(Order::user_id).alias(TopSpender::order_count),
            // Scenario B: Partition + Order for rolling accumulation (SUM(amount) OVER (...))
            Sum(Order::amount)
                .over()
                .partition_by(Order::user_id)
                .order_by(Order::id.asc())
                .alias(TopSpender::total_amount),
            // Scenario C: Multi-field compound partition
            Count(Order::id).over().partition_by((Order::user_id, Order::is_active)), // Checking implicit derivation: passing directly without an alias
        ))
        // Need a massive tuple here to ensure type extraction doesn't break down
        .load_in::<(i32, i32, i64, f64, i64)>()
        .await?;

    Ok(())
}

// ==========================================
// CTE & Subselect Boundary Tests
// ==========================================
async fn compile_check_cte_and_subquery() -> Result<()> {
    let client = Options::from("").build()?;

    let _ = client
        .select::<User>()
        // Scenario A: Seamless CTE injection. Notice the lack of redundant generics or .as_cte() hacks.
        .with::<TopSpender>(
            Subselect::<Order>::columns((
                Order::user_id,
                Sum(Order::amount).alias(Order::amount),
                Sum(Order::amount).alias(TopSpender::total_amount),
                Count(Star).alias(TopSpender::order_count),
            ))
            .group_by(Order::user_id)
            .having(Sum(Order::amount).gt(100.0_f64)),
        )
        .columns((
            User::id,
            User::name,
            TopSpender::total_amount, // Projecting CTE fields directly
            TopSpender::order_count,
        ))
        // Scenario B: Join check. The Relation trait makes no distinction between physical tables and CTEs-both just work.
        .inner_join::<TopSpender>(User::id.eq(TopSpender::user_id))
        // Scenario C: Ensuring virtual columns handle predicates smoothly
        .filter(TopSpender::order_count.ge(5_i64))
        .filter(TopSpender::total_amount.is_not_null())
        // Scenario D: Virtual columns must also support order_by
        .order_by(TopSpender::total_amount.desc())
        .load_in::<(i32, String, f64, i64)>()
        .await?;

    Ok(())
}

// ==========================================
// PG Exclusive Window Functions & Frame Bounds Tests
// ==========================================
async fn compile_check_exclusive_window_functions() -> Result<()> {
    let client = Options::from("").build()?;

    let _ = client
        .select::<Order>()
        .columns((
            Order::id,
            Order::user_id,
            Order::amount,

            // Parameterless ranking window functions.
            // Note: PG natively returns bigint for these, so strictly map them to i64.
            RowNumber.over().partition_by(Order::user_id).order_by(Order::amount.desc()),
            Rank.over().partition_by(Order::user_id).order_by(Order::amount.desc()),
            DenseRank.over().partition_by(Order::user_id).order_by(Order::amount.desc()),

            // Floating-point distribution functions.
            // Note: PG yields double precision here, must map to f64.
            PercentRank.over().partition_by(Order::user_id).order_by(Order::amount.asc()),
            CumeDist.over().partition_by(Order::user_id).order_by(Order::amount.asc()),

            // Bucketing window function.
            // Note: PG returns standard integer, so i32 is the target.
            Ntile(4).over().partition_by(Order::user_id).order_by(Order::amount.desc()),

            // Offset window functions (Lag/Lead).
            // The builder pattern ensures the return type dynamically inherits from the base column (Order::amount is f64).
            Lag(Order::amount)
                .offset(1)
                .default(0.0_f64)
                .over()
                .partition_by(Order::user_id)
                .order_by(Order::id.asc()),

            Lead(Order::amount)
                .over()
                .partition_by(Order::user_id)
                .order_by(Order::id.asc()),

            // Frame Bounds testing.
            Sum(Order::amount)
                .over()
                .partition_by(Order::user_id)
                .order_by(Order::id.asc())
                // Rolling sum: accumulating from the absolute start up to the current row.
                .rows(FrameBound::UnboundedPreceding, Some(FrameBound::CurrentRow)),

            Count(Order::id)
                .over()
                .partition_by(Order::user_id)
                .order_by(Order::amount.asc())
                // Sliding range window: spanning from 1 preceding to 1 following.
                .range(FrameBound::Preceding(1), Some(FrameBound::Following(1))),
        ))
        // The ultimate check: verify that tuple extraction perfectly aligns with the strict return type contracts of every single window function.
        .load_in::<(
            i32, // id
            i32, // user_id
            f64, // amount
            i64, // row_number
            i64, // rank
            i64, // dense_rank
            f64, // percent_rank
            f64, // cume_dist
            i32, // ntile
            f64, // lag
            f64, // lead
            f64, // sum over rows
            i64, // count over range
        )>()
        .await?;

    Ok(())
}